INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','past-perfect','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"past-perfect","title":"Past perfect: the earlier past","level":"B1","order":32,"summary":"The past perfect looks backwards from a past reference point. It marks the earlier event with had + past participle. This is useful when the narrative moves out of chronological order. The later event usually uses past simple. Once the order is clear, a story does not need past perfect in every sentence.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Connect two points in time","Build the perfect verb","Negatives and questions","Time expressions and short answers"],"rules":[{"title":"Connect two points in time","explanation":"The past perfect looks backwards from a past reference point. It marks the earlier event with had + past participle. This is useful when the narrative moves out of chronological order. The later event usually uses past simple. Once the order is clear, a story does not need past perfect in every sentence.","pattern":"Subject + **had / had + past participle**","commonMistakes":["Before and after can already show the sequence, so past simple is sometimes enough. Past perfect is not required merely because an event happened a long time ago."],"examples":["Use the past perfect: She **had prepared** the visitor guide before the inspection began.","Use the past perfect: She **had restored** the old portrait before the inspection began."],"skill":"form"},{"title":"Build the perfect verb","explanation":"A perfect construction uses **have as an auxiliary**, followed by a past participle. Regular participles normally end in -ed. Irregular ones must be learned with their base and past forms: write / wrote / written. Do not substitute an -ing form unless you also build the continuous construction.","pattern":"She **had written**. / They **had written**.","commonMistakes":["The form written is a participle; wrote is past simple. They are not interchangeable after have."],"examples":["Make a past-perfect negative: They **had not prepared** the visitor guide before the inspection began.","Make a past-perfect negative: They **had not restored** the old portrait before the inspection began."],"skill":"meaning"},{"title":"Negatives and questions","explanation":"Put **not after had or had**. For a yes/no question, move the auxiliary before the subject. The participle stays unchanged. There is no extra do or did because the perfect construction already contains an auxiliary.","pattern":"Had they finished? / They **had not finished**.","commonMistakes":["Do not combine did with a perfect auxiliary to make its negative or question."],"examples":["Begin this past-perfect question: **Had** they prepared the visitor guide before the inspection began?","Begin this past-perfect question: **Had** they restored the old portrait before the inspection began?"],"skill":"contrast"},{"title":"Time expressions and short answers","explanation":"Read the whole sentence to locate the reference time. Here it is **before the inspection began**. Keep the appropriate form of have in a short answer and omit the repeated participle. Since names a starting point; for names a duration. Neither word automatically selects a single tense.","pattern":"Yes, they **had**. / No, they **had not**.","commonMistakes":["Been can describe a completed visit; gone often means the person has left and has not yet returned."],"examples":["Choose the participle for the past perfect: We had **prepared** the visitor guide before the inspection began. (prepare)","Choose the participle for the past perfect: We had **restored** the old portrait before the inspection began. (restore)"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"aa8a057b-b245-5be1-a8e0-e4114946c5d6","topicSlug":"past-perfect","level":"B1","prompt":"Use the past perfect: She ____ the visitor guide before the inspection began.","choices":[{"id":"A","text":"had to prepare"},{"id":"B","text":"had been preparing"},{"id":"C","text":"had prepared"},{"id":"D","text":"had preparing"}],"answerId":"C","hint":"Find the past reference and use **have + past participle**, with the auxiliary in the appropriate tense.","explanation":"The requested past perfect needs **had + prepared** with she. The reference is before the inspection began.","keywords":["perfect-affirmative"],"skill":"perfect-affirmative","contextKey":"past-perfect-1","fingerprint":"d4b1b9d1095a836c50471acb4e32036dfe1cb03567308fc11ce33f01a8248f93","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the past reference and use **have + past participle**, with the auxiliary in the appropriate tense.","The requested past perfect needs **had + prepared** with she. The reference is before the inspection began.","Choose **had prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An infinitive cannot follow the perfect auxiliary here.","B":"This is a perfect continuous form; the instruction specifically asks for perfect simple.","C":"The requested past perfect needs **had + prepared** with she. The reference is before the inspection began.","D":"The perfect simple takes a past participle, not an -ing form."}}},{"id":"c7371b6d-d9ee-5c77-a4e9-b3c7e237e5bb","topicSlug":"past-perfect","level":"B1","prompt":"Make a past-perfect negative: They ____ the visitor guide before the inspection began.","choices":[{"id":"A","text":"had not preparing"},{"id":"B","text":"not had prepared"},{"id":"C","text":"had not prepared"},{"id":"D","text":"did not had prepared"}],"answerId":"C","hint":"Keep the past-perfect auxiliary and add **not** immediately after it.","explanation":"Place **not after had** and keep **prepared**: they had not prepared.","keywords":["perfect-negative"],"skill":"perfect-negative","contextKey":"past-perfect-1","fingerprint":"7cf7b2ea2291c570fb42e8b20ae34c864b73a6f89fbf45235215dd6212ac0c52","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the past-perfect auxiliary and add **not** immediately after it.","Place **not after had** and keep **prepared**: they had not prepared.","Choose **had not prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The -ing form needs been for a perfect continuous, which is not requested.","B":"In the standard finite negative, not follows the auxiliary.","C":"Place **not after had** and keep **prepared**: they had not prepared.","D":"Perfect negatives do not add did; not follows the existing auxiliary."}}},{"id":"028d67ab-2215-5bb9-a9ea-bec1eafda4dd","topicSlug":"past-perfect","level":"B1","prompt":"Begin this past-perfect question: ____ they prepared the visitor guide before the inspection began?","choices":[{"id":"A","text":"Had"},{"id":"B","text":"Did"},{"id":"C","text":"Are"},{"id":"D","text":"Has"}],"answerId":"A","hint":"The first auxiliary moves before the subject; do not add a new auxiliary.","explanation":"Move **had** before they. The participle prepared remains after the subject.","keywords":["perfect-question"],"skill":"perfect-question","contextKey":"past-perfect-1","fingerprint":"758bd721b587e07bdf8935dd5555391bf479d9d4bc456fa24e466e57bab528ac","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary moves before the subject; do not add a new auxiliary.","Move **had** before they. The participle prepared remains after the subject.","Choose **Had**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Move **had** before they. The participle prepared remains after the subject.","B":"Did would require a base verb and would not make this perfect question.","C":"Are would create a different structure, not the requested perfect.","D":"Has does not agree with they, and cannot form a past-perfect question."}}},{"id":"fbc03ed0-0505-5ba4-a0f0-f4b3c4ee2870","topicSlug":"past-perfect","level":"B1","prompt":"Choose the participle for the past perfect: We had ____ the visitor guide before the inspection began. (prepare)","choices":[{"id":"A","text":"been preparing"},{"id":"B","text":"prepared"},{"id":"C","text":"preparing"},{"id":"D","text":"to prepare"}],"answerId":"B","hint":"Identify the past participle, rather than choosing a word only because it looks past.","explanation":"The past participle of **prepare** is **prepared**. It follows had in the requested perfect construction.","keywords":["perfect-participle"],"skill":"perfect-participle","contextKey":"past-perfect-1","fingerprint":"ed5fe355f46584fec627366f0768b04c1a783df58129114f4222101c38b73821","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Identify the past participle, rather than choosing a word only because it looks past.","The past participle of **prepare** is **prepared**. It follows had in the requested perfect construction.","Choose **prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This would make a perfect continuous construction, not perfect simple.","B":"The past participle of **prepare** is **prepared**. It follows had in the requested perfect construction.","C":"This is the -ing form, not the past participle.","D":"This is the to-infinitive, not a past participle."}}},{"id":"58ab016c-f618-5064-a8c2-0a8c2621ba9b","topicSlug":"past-perfect","level":"B1","prompt":"Use the past perfect: She ____ the old portrait before the inspection began.","choices":[{"id":"A","text":"had restoring"},{"id":"B","text":"had to restore"},{"id":"C","text":"had been restoring"},{"id":"D","text":"had restored"}],"answerId":"D","hint":"Find the past reference and use **have + past participle**, with the auxiliary in the appropriate tense.","explanation":"The requested past perfect needs **had + restored** with she. The reference is before the inspection began.","keywords":["perfect-affirmative"],"skill":"perfect-affirmative","contextKey":"past-perfect-2","fingerprint":"f0bffd0f9fb9ac5e23c410250ada1cf390478355cc35a87f97d896a10289b496","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the past reference and use **have + past participle**, with the auxiliary in the appropriate tense.","The requested past perfect needs **had + restored** with she. The reference is before the inspection began.","Choose **had restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The perfect simple takes a past participle, not an -ing form.","B":"An infinitive cannot follow the perfect auxiliary here.","C":"This is a perfect continuous form; the instruction specifically asks for perfect simple.","D":"The requested past perfect needs **had + restored** with she. The reference is before the inspection began."}}},{"id":"ebf30f11-2726-570b-aca3-662e8b12a3cd","topicSlug":"past-perfect","level":"B1","prompt":"Make a past-perfect negative: They ____ the old portrait before the inspection began.","choices":[{"id":"A","text":"had not restored"},{"id":"B","text":"did not had restored"},{"id":"C","text":"had not restoring"},{"id":"D","text":"not had restored"}],"answerId":"A","hint":"Keep the past-perfect auxiliary and add **not** immediately after it.","explanation":"Place **not after had** and keep **restored**: they had not restored.","keywords":["perfect-negative"],"skill":"perfect-negative","contextKey":"past-perfect-2","fingerprint":"e76ae07738fcb6c2feee5fdb8195c6f25733e5be51cd79635375801164eeb540","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the past-perfect auxiliary and add **not** immediately after it.","Place **not after had** and keep **restored**: they had not restored.","Choose **had not restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Place **not after had** and keep **restored**: they had not restored.","B":"Perfect negatives do not add did; not follows the existing auxiliary.","C":"The -ing form needs been for a perfect continuous, which is not requested.","D":"In the standard finite negative, not follows the auxiliary."}}},{"id":"c6a26b98-0f71-5650-a803-ec0277422e8c","topicSlug":"past-perfect","level":"B1","prompt":"Begin this past-perfect question: ____ they restored the old portrait before the inspection began?","choices":[{"id":"A","text":"Has"},{"id":"B","text":"Had"},{"id":"C","text":"Did"},{"id":"D","text":"Are"}],"answerId":"B","hint":"The first auxiliary moves before the subject; do not add a new auxiliary.","explanation":"Move **had** before they. The participle restored remains after the subject.","keywords":["perfect-question"],"skill":"perfect-question","contextKey":"past-perfect-2","fingerprint":"12719f8dd3b48c0996ae5ff28060ced487a8fb22a236248069bfddcf430a7a77","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary moves before the subject; do not add a new auxiliary.","Move **had** before they. The participle restored remains after the subject.","Choose **Had**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Has does not agree with they, and cannot form a past-perfect question.","B":"Move **had** before they. The participle restored remains after the subject.","C":"Did would require a base verb and would not make this perfect question.","D":"Are would create a different structure, not the requested perfect."}}},{"id":"f0c71d0c-e696-5ce4-ab32-5e3fa74e8fb6","topicSlug":"past-perfect","level":"B1","prompt":"Choose the participle for the past perfect: We had ____ the old portrait before the inspection began. (restore)","choices":[{"id":"A","text":"restored"},{"id":"B","text":"restoring"},{"id":"C","text":"to restore"},{"id":"D","text":"been restoring"}],"answerId":"A","hint":"Identify the past participle, rather than choosing a word only because it looks past.","explanation":"The past participle of **restore** is **restored**. It follows had in the requested perfect construction.","keywords":["perfect-participle"],"skill":"perfect-participle","contextKey":"past-perfect-2","fingerprint":"be724470abd9bc9c91bb91fb344282028fbf2ce4ddda8ca6ed7842a1345164ab","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Identify the past participle, rather than choosing a word only because it looks past.","The past participle of **restore** is **restored**. It follows had in the requested perfect construction.","Choose **restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The past participle of **restore** is **restored**. It follows had in the requested perfect construction.","B":"This is the -ing form, not the past participle.","C":"This is the to-infinitive, not a past participle.","D":"This would make a perfect continuous construction, not perfect simple."}}},{"id":"38dcff36-a6e4-5b8e-a63b-008d05077225","topicSlug":"past-perfect","level":"B1","prompt":"Use the past perfect: She ____ the garden fence before the inspection began.","choices":[{"id":"A","text":"had to measure"},{"id":"B","text":"had been measuring"},{"id":"C","text":"had measured"},{"id":"D","text":"had measuring"}],"answerId":"C","hint":"Find the past reference and use **have + past participle**, with the auxiliary in the appropriate tense.","explanation":"The requested past perfect needs **had + measured** with she. The reference is before the inspection began.","keywords":["perfect-affirmative"],"skill":"perfect-affirmative","contextKey":"past-perfect-3","fingerprint":"431a01e9f110ce8f3bd09bfdfa14a40e2ef8b96ae31f96bc0aed95b8f8fa6cde","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the past reference and use **have + past participle**, with the auxiliary in the appropriate tense.","The requested past perfect needs **had + measured** with she. The reference is before the inspection began.","Choose **had measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An infinitive cannot follow the perfect auxiliary here.","B":"This is a perfect continuous form; the instruction specifically asks for perfect simple.","C":"The requested past perfect needs **had + measured** with she. The reference is before the inspection began.","D":"The perfect simple takes a past participle, not an -ing form."}}},{"id":"98696019-5180-5a12-a84c-f439e5494e2b","topicSlug":"past-perfect","level":"B1","prompt":"Make a past-perfect negative: They ____ the garden fence before the inspection began.","choices":[{"id":"A","text":"had not measuring"},{"id":"B","text":"not had measured"},{"id":"C","text":"had not measured"},{"id":"D","text":"did not had measured"}],"answerId":"C","hint":"Keep the past-perfect auxiliary and add **not** immediately after it.","explanation":"Place **not after had** and keep **measured**: they had not measured.","keywords":["perfect-negative"],"skill":"perfect-negative","contextKey":"past-perfect-3","fingerprint":"84761bccb9d352cea01ea865e310470ea30ed3f52d16576060dc2ba2aff3a318","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the past-perfect auxiliary and add **not** immediately after it.","Place **not after had** and keep **measured**: they had not measured.","Choose **had not measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The -ing form needs been for a perfect continuous, which is not requested.","B":"In the standard finite negative, not follows the auxiliary.","C":"Place **not after had** and keep **measured**: they had not measured.","D":"Perfect negatives do not add did; not follows the existing auxiliary."}}},{"id":"e2985e5b-73fa-585a-a04a-14bfa8273607","topicSlug":"past-perfect","level":"B1","prompt":"Begin this past-perfect question: ____ they measured the garden fence before the inspection began?","choices":[{"id":"A","text":"Has"},{"id":"B","text":"Had"},{"id":"C","text":"Did"},{"id":"D","text":"Are"}],"answerId":"B","hint":"The first auxiliary moves before the subject; do not add a new auxiliary.","explanation":"Move **had** before they. The participle measured remains after the subject.","keywords":["perfect-question"],"skill":"perfect-question","contextKey":"past-perfect-3","fingerprint":"68053f8f6e35627698acbc1b1419f66a22520a9ba15965f1a0a657549f19da74","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary moves before the subject; do not add a new auxiliary.","Move **had** before they. The participle measured remains after the subject.","Choose **Had**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Has does not agree with they, and cannot form a past-perfect question.","B":"Move **had** before they. The participle measured remains after the subject.","C":"Did would require a base verb and would not make this perfect question.","D":"Are would create a different structure, not the requested perfect."}}},{"id":"bfde6111-4eaf-593d-a3c1-19594a9577fd","topicSlug":"past-perfect","level":"B1","prompt":"Choose the participle for the past perfect: We had ____ the garden fence before the inspection began. (measure)","choices":[{"id":"A","text":"to measure"},{"id":"B","text":"been measuring"},{"id":"C","text":"measured"},{"id":"D","text":"measuring"}],"answerId":"C","hint":"Identify the past participle, rather than choosing a word only because it looks past.","explanation":"The past participle of **measure** is **measured**. It follows had in the requested perfect construction.","keywords":["perfect-participle"],"skill":"perfect-participle","contextKey":"past-perfect-3","fingerprint":"c272a64bd8531b3a62beefef2692a85d3344afcbb37eda12a0055ced54c847a3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Identify the past participle, rather than choosing a word only because it looks past.","The past participle of **measure** is **measured**. It follows had in the requested perfect construction.","Choose **measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is the to-infinitive, not a past participle.","B":"This would make a perfect continuous construction, not perfect simple.","C":"The past participle of **measure** is **measured**. It follows had in the requested perfect construction.","D":"This is the -ing form, not the past participle."}}},{"id":"379686dd-e433-59b6-a88b-93ff16940ea0","topicSlug":"past-perfect","level":"B1","prompt":"Use the past perfect: She ____ the travel leaflet before the inspection began.","choices":[{"id":"A","text":"had translating"},{"id":"B","text":"had to translate"},{"id":"C","text":"had been translating"},{"id":"D","text":"had translated"}],"answerId":"D","hint":"Find the past reference and use **have + past participle**, with the auxiliary in the appropriate tense.","explanation":"The requested past perfect needs **had + translated** with she. The reference is before the inspection began.","keywords":["perfect-affirmative"],"skill":"perfect-affirmative","contextKey":"past-perfect-4","fingerprint":"ee57cdb3dd758273923123fec735dba740ff119f0e96cb9e8cca507a390d1ba3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find the past reference and use **have + past participle**, with the auxiliary in the appropriate tense.","The requested past perfect needs **had + translated** with she. The reference is before the inspection began.","Choose **had translated**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The perfect simple takes a past participle, not an -ing form.","B":"An infinitive cannot follow the perfect auxiliary here.","C":"This is a perfect continuous form; the instruction specifically asks for perfect simple.","D":"The requested past perfect needs **had + translated** with she. The reference is before the inspection began."}}},{"id":"3b86499e-748f-5615-a7a2-27a8faea1271","topicSlug":"past-perfect","level":"B1","prompt":"Make a past-perfect negative: They ____ the travel leaflet before the inspection began.","choices":[{"id":"A","text":"did not had translated"},{"id":"B","text":"had not translating"},{"id":"C","text":"not had translated"},{"id":"D","text":"had not translated"}],"answerId":"D","hint":"Keep the past-perfect auxiliary and add **not** immediately after it.","explanation":"Place **not after had** and keep **translated**: they had not translated.","keywords":["perfect-negative"],"skill":"perfect-negative","contextKey":"past-perfect-4","fingerprint":"4bfc7bf04546c5874909cf6aaf1bb2d5259b1835e5aaf7b9e124160654965e55","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the past-perfect auxiliary and add **not** immediately after it.","Place **not after had** and keep **translated**: they had not translated.","Choose **had not translated**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Perfect negatives do not add did; not follows the existing auxiliary.","B":"The -ing form needs been for a perfect continuous, which is not requested.","C":"In the standard finite negative, not follows the auxiliary.","D":"Place **not after had** and keep **translated**: they had not translated."}}},{"id":"83f8ddf8-34d2-5824-a785-d1c7c7f2b473","topicSlug":"past-perfect","level":"B1","prompt":"Begin this past-perfe